package app.kinnect.live;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import org.json.*;
public final class WalletActivity extends Activity {
 private CommerceUi ui;private JSONObject wallet;private boolean hidden;
 public void setContentView(View view){super.setContentView(CommerceChrome.wrap(this,view));}
 protected void attachBaseContext(Context c){super.attachBaseContext(I18n.localized(c));}
 public void onCreate(Bundle b){super.onCreate(b);ui=new CommerceUi(this);getWindow().setStatusBarColor(ui.bg);getWindow().setNavigationBarColor(ui.bg);getWindow().getDecorView().setSystemUiVisibility(WebTheme.isDark(this)?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);NativeApi.shared.initialize(this,ServerConfig.DEFAULT_ORIGIN);load();}
 private String number(long value){return java.text.NumberFormat.getIntegerInstance(new java.util.Locale("vi","VN")).format(value);}
 private void load(){LinearLayout page=ui.col();page.setBackgroundColor(ui.bg);page.addView(ui.header("Ví"));page.addView(ui.empty("wallet","Đang tải…"));setContentView(page);NativeApi.shared.call("GET","/api/wallet",null,(data,error,status)->{if(isFinishing()||isDestroyed())return;if(error!=null){page.removeViewAt(1);page.addView(ui.empty("wallet","Chưa tải được ví"));page.addView(ui.action("Thử lại","refresh_cw",this::load));return;}draw(data);});}
 private void info(){new Sheet(this).setTitle(I18n.t("Ví Kinnect")).setMessage(I18n.t("Xu tặng và quà nhận từ xu tặng không rút được. Xu mua còn dư được rút theo tỷ lệ quy đổi. Quà từ xu mua tạo thu nhập sau phí và hoàn tiền: người nhận 75%, nền tảng 25%. Không cộng trùng xu mua đã gửi quà. Nạp và rút tiền thật chưa mở.")).setPositiveButton(I18n.t("Đóng"),null).show();}
 private void draw(JSONObject w){wallet=w;if(ui==null)ui=new CommerceUi(this);LinearLayout root=ui.col();root.setBackgroundColor(ui.bg);root.addView(ui.header("Ví",ui.icon("info","Thông tin ví",this::info),ui.icon("refresh_cw","Làm mới",this::load)));ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);LinearLayout page=ui.col();page.setPadding(ui.dp(16),ui.dp(8),ui.dp(16),ui.dp(24));scroll.addView(page);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);
  page.addView(new CoinBalanceCard(this,w,false,hidden,()->{hidden=!hidden;draw(wallet);}));
  LinearLayout shortcuts=ui.row();shortcuts.setGravity(Gravity.TOP);String[][] actions={{"plus","Nạp xu"},{"arrow_up_right","Rút tiền"},{"shopping_bag","Cửa hàng"}};for(int n=0;n<actions.length;n++){final int index=n;LinearLayout cell=ui.col();cell.setGravity(Gravity.CENTER);cell.setPadding(ui.dp(4),ui.dp(16),ui.dp(4),ui.dp(12));cell.addView(ui.icon(actions[n][0],actions[n][1],()->{if(index==2)ui.go(StoreActivity.class);else if(index==0)topUp();else ui.moneyUnavailable("Rút tiền");}),new LinearLayout.LayoutParams(ui.dp(48),ui.dp(48)));TextView t=ui.text(actions[n][1],12,ui.ink,true);t.setGravity(Gravity.CENTER);t.setPadding(0,ui.dp(7),0,0);cell.addView(t);shortcuts.addView(cell,new LinearLayout.LayoutParams(0,-2,1));}page.addView(shortcuts);
  LinearLayout income=ui.section();LinearLayout title=ui.row();title.addView(ui.text("Tiền có thể rút",13,ui.muted,false),new LinearLayout.LayoutParams(0,-2,1));title.addView(ui.badge("Chưa mở rút"));income.addView(title);TextView earned=ui.text(hidden?"••••":number(w.optLong("withdrawableVnd",w.optLong("earningsVnd")))+"đ",26,ui.ink,true);earned.setTag("wallet:earnings");earned.setPadding(0,ui.dp(10),0,0);income.addView(earned);ui.add(income,ui.text("Xu mua còn dư + thu nhập quà xu mua",11,ui.muted,false),6);ui.add(page,income,8);LinearLayout trialGifts=ui.section();trialGifts.addView(ui.text("Quà nhận từ xu tặng",13,ui.muted,false));trialGifts.addView(ui.text(number(w.optLong("giftedGiftValueCoins"))+" "+I18n.t("xu")+" · "+I18n.t("Không rút"),18,ui.ink,true));ui.add(page,trialGifts,12);
  TextView history=ui.text("Giao dịch",17,ui.ink,true);history.setPadding(ui.dp(2),ui.dp(24),0,ui.dp(12));page.addView(history);JSONArray entries=w.optJSONArray("entries");LinearLayout list=ui.section();list.setTag("wallet:history");if(entries==null||entries.length()==0)list.addView(ui.empty("gift","Chưa có giao dịch"));else for(int n=0;n<entries.length();n++){JSONObject entry=entries.optJSONObject(n);if(entry==null)continue;LinearLayout row=ui.row();row.setPadding(0,ui.dp(10),0,ui.dp(10));ImageView glyph=new ImageView(this);glyph.setImageDrawable(ui.glyph("gift",ui.purple,22));row.addView(glyph,new LinearLayout.LayoutParams(ui.dp(32),ui.dp(36)));LinearLayout copy=ui.col();copy.setPadding(ui.dp(8),0,ui.dp(6),0);String kind=entry.optString("kind");boolean paidCoins=kind.equals("store_paid")||kind.equals("coin_purchase")||kind.equals("live_gift_paid");boolean trial=kind.equals("signup_trial")||kind.equals("live_gift_trial")||kind.equals("store_trial")||kind.equals("admin_trial");copy.addView(ui.text(kind.equals("signup_trial")?"Xu chào mừng":(kind.equals("store_trial")||kind.equals("store_paid"))?"Gói cửa hàng":kind.equals("admin_trial")?"Xu được tặng":"Quà Live",13,ui.ink,true));String date=new java.text.SimpleDateFormat("dd/MM · HH:mm",java.util.Locale.getDefault()).format(new java.util.Date(entry.optLong("created")));copy.addView(ui.text(date,11,ui.muted,false));row.addView(copy,new LinearLayout.LayoutParams(0,-2,1));TextView amount=ui.text(hidden?"••••":(trial||paidCoins)?(entry.optLong("coins")>0?"+":"")+number(entry.optLong("coins"))+" "+I18n.t("xu"):"+"+number(entry.optLong("creatorVnd"))+"đ",14,ui.purple,true);amount.setGravity(Gravity.END);row.addView(amount,new LinearLayout.LayoutParams(0,-2,1));row.setOnClickListener(v->new Sheet(this).setTitle(I18n.t("Chi tiết giao dịch")).setMessage(I18n.t(trial?"Xu tặng":paidCoins?"Xu mua":"Thu nhập từ quà xu mua")+"\n"+number(entry.optLong(trial||paidCoins?"coins":"creatorVnd"))+(trial||paidCoins?" "+I18n.t("xu"):"đ")+"\n"+date+"\n\n"+I18n.t(trial?"Xu tặng không quy đổi thành tiền.":"Tỷ lệ chia áp dụng sau phí thanh toán và hoàn tiền.")).setPositiveButton(I18n.t("Đóng"),null).show());list.addView(row);}page.addView(list);
 }
 private void topUp(){LinearLayout body=ui.col();body.addView(ui.badge("1 "+I18n.t("xu")+" = "+number(wallet.optLong("vndPerCoin",100))+"đ"));JSONArray packs=wallet.optJSONArray("coinPacks");final Button unavailable=ui.action("Chưa mở nạp",null,()->{});unavailable.setEnabled(false);LinearLayout row=null;for(int i=0;packs!=null&&i<packs.length();i++){JSONObject pack=packs.optJSONObject(i);if(pack==null)continue;if(i%2==0){row=ui.row();body.addView(row);}LinearLayout option=ui.section();TextView coins=ui.text(number(pack.optLong("coins"))+" "+I18n.t("xu"),17,ui.purple,true);coins.setGravity(Gravity.CENTER);option.addView(coins);TextView price=ui.text(number(pack.optLong("referenceVnd"))+"đ",13,ui.muted,false);price.setGravity(Gravity.CENTER);option.addView(price);option.setContentDescription(coins.getText()+" · "+price.getText());option.setOnClickListener(v->{for(int n=0;n<body.getChildCount();n++){View child=body.getChildAt(n);if(child instanceof LinearLayout)for(int k=0;k<((LinearLayout)child).getChildCount();k++){View c=((LinearLayout)child).getChildAt(k);if(c instanceof LinearLayout)c.setBackground(ui.round(ui.card,20));}}option.setBackground(ui.round(ui.soft,20));});LinearLayout.LayoutParams slot=new LinearLayout.LayoutParams(0,-2,1);slot.setMargins(ui.dp(4),ui.dp(6),ui.dp(4),ui.dp(6));row.addView(option,slot);}if(packs==null||packs.length()==0)body.addView(ui.empty("wallet","Chưa có gói nạp"));TextView note=ui.text("Đang kết nối thanh toán",12,ui.muted,false);note.setGravity(Gravity.CENTER);ui.add(body,note,12);ui.add(body,unavailable,10);ScrollView scroller=new ScrollView(this){protected void onMeasure(int w,int h){super.onMeasure(w,View.MeasureSpec.makeMeasureSpec(getResources().getDisplayMetrics().heightPixels*65/100,View.MeasureSpec.AT_MOST));}};scroller.addView(body);new Sheet(this).setTitle(I18n.t("Nạp xu")).setView(scroller).show();
 }

}
